import { useCallback, useEffect, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Button, CustomText } from '../../../components'
import BottomActionSheet from '../../../components/BottomActionSheet'
import DynamicForm from '../../../components/DynamicForm'
import ShowSnackbar from '../../../components/ShowNotification'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { MV_RENEWAL_FLOW } from '../../../constants/pkgCode'
import { regex } from '../../../constants/regex'
import { ICON_CHASIS_NUMBER } from '../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../lang/index'
import { useGetMvRenewalDetails } from '../../../containers/Private/Policy/state/hooks/usePolicyState'
import { usePolicyContextValue } from '../../../containers/Private/Policy/context'
import { ContentContainer, IconContainer, ChasisNumberInputWrapper } from '../container/index.style'

const CHASIS_NUMBER_FORM = [
  {
    type: 'inputV2',
    title: LANG_STRINGS.chassisNumber,
    name: 'chasis_number',
    required: true,
    regex_validation: regex.mvChasisNumber,
    errormsg: LANG_STRINGS.consist8to20CharactersChasisNumber,
  },
]

function ChasisNumberInput({
  show,
  renewalFlow,
  onClose,
  onSearchSuccess,
  onClickUploadDocument,
  onClickSkip,
}) {
  const formRef = useRef()
  const [formData, setFormData] = useState('')

  const [{ getMvRenewalDetailsData }, getMvRenewalDetailsRequest] = useGetMvRenewalDetails()
  const [, , dispatchSetPolicyState] = usePolicyContextValue()
  const [{ getMvRenewalDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  const handleClickSearch = useCallback(() => {
    if (!formRef.current?.validateFormValues()) return
    getMvRenewalDetailsRequest({
      query: {
        chasis_number: formData.chasis_number,
        flow: MV_RENEWAL_FLOW.EXISTING_CAR,
      },
    })
  }, [formData, getMvRenewalDetailsRequest])

  useEffect(() => {
    if (getMvRenewalDetailsData?.data && Object.keys(getMvRenewalDetailsData?.data).length > 0) {
      ShowSnackbar.success({ text: ERROR_LANG.generalSuccessPleaseContinue })
      onSearchSuccess(getMvRenewalDetailsData?.data)
      dispatchSetPolicyState({ getMvRenewalDetailsData: null })
      resetError(['getMvRenewalDetailsStatus'])
    }
  }, [onSearchSuccess, dispatchSetPolicyState, resetError, getMvRenewalDetailsData])

  useEffect(() => {
    if (!!getMvRenewalDetailsStatus && getMvRenewalDetailsStatus !== 'success') {
      ShowSnackbar.error({ text: ERROR_LANG.generalErrorTryAgain })
      resetError(['getMvRenewalDetailsStatus'])
    }
  }, [getMvRenewalDetailsStatus, resetError])

  return createPortal(
    <BottomActionSheet onCloseSheet={onClose} show={show} zIndex={5} showHeader>
      <ContentContainer>
        <IconContainer>
          <img src={ICON_CHASIS_NUMBER} alt="" />
        </IconContainer>
        <CustomText
          color={AgentColorPallette.darkCharcoal}
          size="0.9em"
          weight={800}
          textAlign="center"
          marginBottom="8px"
        >
          {LANG_STRINGS.buyMvPolicy}
        </CustomText>
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size="0.8em"
          weight={600}
          textAlign="center"
          marginBottom="24px"
        >
          {LANG_STRINGS.renewalsEnterVehicleChasisNumber}
        </CustomText>

        <ChasisNumberInputWrapper>
          <DynamicForm
            ref={formRef}
            formName="chasis-number-input"
            form={CHASIS_NUMBER_FORM}
            onChange={(data) => setFormData(data)}
            isValidateOnChange
          />
          <Button variant="filled" handleClick={handleClickSearch}>
            <i className="fas fa-angle-right arrow-gray" />
          </Button>
        </ChasisNumberInputWrapper>

        <CustomText
          color={AgentColorPallette.black}
          size="0.8em"
          weight={800}
          textAlign="center"
          marginBottom="16px"
        >
          {LANG_STRINGS.or}
        </CustomText>

        {renewalFlow === MV_RENEWAL_FLOW.EXISTING_CAR && (
          <Button variant="filled" handleClick={onClickUploadDocument} style={{ marginBottom: 8 }}>
            {LANG_STRINGS.uploadPolicyDocument}
          </Button>
        )}
        <Button variant="outlined" handleClick={onClickSkip}>
          {LANG_STRINGS.skip2}
        </Button>
      </ContentContainer>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  )
}

export default ChasisNumberInput
