import { useCallback, useEffect, useRef, useState } from 'react'
import { useHistory } from 'react-router'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { openUrlInBrowser } from '../../../../../../bridges'
import { Container } from '../../../../../../components'
import MVChasisNumberCheckModal from '../../../../../../components/MVChasisNumberCheckModal'
import {
  CAR_PROTECTION,
  MV_RENEWAL_FLOW,
  NEW_PURCHASE,
  RENEW_PURCHASE,
} from '../../../../../../constants/pkgCode'
import { LANG_STRINGS } from '../../../../../../lang'
import { removeFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { useGetAgentDetails } from '../../../../../../state/globalState/hooks/useGlobalContext'
import { OFFLINE_MANUAL_FORM_DATA } from '../../OfflineProductManualOrder/constant'
import { OFFLINE_PRODUCTS_DATA, getLarkUrl } from '../constants'
import { OfflineProductTypeStyle, ProductTypeCard } from './index.style'

function OfflineProductTypeContainer() {
  const history = useHistory()
  const that = useRef({ product: null })

  const [showMvChasisNumberCheckModal, setShowMvChasisNumberCheckModal] = useState(false)

  const [{ getAgentDetailData }] = useGetAgentDetails()
  const [{ GET_AGENT_DETAIL_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    // On load of this page, remove cache from local storage
    removeFromLocalStorageData(OFFLINE_MANUAL_FORM_DATA)
  }, [])

  const handleSelectProduct = (product) => {
    switch (product.code) {
      case CAR_PROTECTION:
        setShowMvChasisNumberCheckModal(true)
        that.current.product = product
        break
      default:
        const larkUrl = getLarkUrl(getAgentDetailData, product?.larkCode)
        openUrlInBrowser(larkUrl, () => window.open(larkUrl, '_blank'))
        break
    }
  }

  const handleBeginMvPolicy = useCallback(
    (purchaseType, purchaseRenewFlow, vehicleData) => {
      setShowMvChasisNumberCheckModal(false)

      history.push({
        pathname: `/${CAR_PROTECTION}/form/1`,
        state: {
          package_type: that.current.product?.package_type,
          name: that.current.product?.name,
          productCode: CAR_PROTECTION,
          purchaseType,
          purchaseRenewFlow,
          vehicleData,
          isSameAgent: vehicleData?.is_same_agent,
        },
      })
    },
    [history]
  )

  return (
    <Container
      title={LANG_STRINGS.productList}
      hideBottomTabs
      displayBackButton
      loader={GET_AGENT_DETAIL_LOADER}
    >
      <OfflineProductTypeStyle>
        <div>
          {OFFLINE_PRODUCTS_DATA.map((product) => (
            <ProductTypeCard key={product.code} onClick={() => handleSelectProduct(product)}>
              <img src={product.icon} alt="" />
              <span>{product.name}</span>
            </ProductTypeCard>
          ))}
        </div>

        {showMvChasisNumberCheckModal && (
          <MVChasisNumberCheckModal
            show={showMvChasisNumberCheckModal}
            renewalFlow={MV_RENEWAL_FLOW.O2O}
            onClose={() => setShowMvChasisNumberCheckModal(false)}
            onBeginNewPurchase={(vehicleData) =>
              handleBeginMvPolicy(NEW_PURCHASE, null, vehicleData)
            }
            onBeginRenewal={(vehicleData) => {
              handleBeginMvPolicy(RENEW_PURCHASE, MV_RENEWAL_FLOW.O2O, vehicleData)
            }}
          />
        )}
      </OfflineProductTypeStyle>
    </Container>
  )
}

export default OfflineProductTypeContainer
