export function getLarkUrl(agentDetail, larkCode) {
  if (!agentDetail || !larkCode) return null

  const url = process.env.REACT_APP_OFFLINE_POLICY_LARKFORM
  const lvAdminEmail = 'hana.mona@pasarpolis.com'

  const isLvAgent = checkIsLvAgent(agentDetail)
  const params = {
    'prefill_Jenis+Product': larkCode,
    'hide_Jenis+Product': '1',
    'prefill_Agent+Email': encodeURIComponent(agentDetail?.email || '-'),
    'hide_Agent+Email': '1',
    'prefill_Agent+Code': encodeURIComponent(agentDetail?.agent_code || '-'),
    'hide_Agent+Code': '1',
    'prefill_Agent+Type': agentDetail?.category || 'Retail',
    'hide_Agent+Type': '1',
    'prefill_Agent+RM+Email': isLvAgent
      ? encodeURIComponent(lvAdminEmail)
      : encodeURIComponent(agentDetail?.tag_handler_details?.email || '-'),
    'hide_Agent+RM+Email': '1',
  }

  return `${url}?${Object.entries(params)
    .map(([key, value]) => `${key}=${value}`)
    .join('&')}`
}
